import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { useAuth } from "../../context/AuthContext";
import Navbar from "../../components/Navbar";
import { FaCloudUploadAlt, FaTimes } from "react-icons/fa";
import "./AddPetPage.css";

const AddPetPage = () => {
    const { user } = useAuth();
    const navigate = useNavigate();

    // Store the list of image strings
    const [images, setImages] = useState([]);
    const [loading, setLoading] = useState(false);

    const [formData, setFormData] = useState({
        name: "", breed: "", age: "", type: "Dog",
        gender: "Male", color: "", description: "",
        adoptionStatus: "AVAILABLE", // Default status
        shelterEmail: user?.email || ""
    });

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    // 1. Convert Files to Base64 strings
    const handleImageChange = (e) => {
        const files = Array.from(e.target.files);

        files.forEach(file => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onloadend = () => {
                setImages((prev) => [...prev, reader.result]);
            };
        });
    };

    // 2. Remove an image before saving
    const removeImage = (index) => {
        setImages(images.filter((_, i) => i !== index));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            const petData = {
                ...formData,
                age: parseInt(formData.age), // Ensure Age is an Integer for Java
                ownerId: user.uid,
                imageUrl: images[0] || "",   // Set first image as main thumbnail
                images: images               // Send the full list
            };

            await axios.post("http://localhost:8080/pets", petData);
            alert("Pet added successfully!");
            navigate("/");
        } catch (error) {
            console.error("Error adding pet:", error);
            alert("Failed to add pet.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="add-pet-container">
            <div className="form-wrapper">
                <h2>Add a New Pet 🐾</h2>
                <form onSubmit={handleSubmit}>

                    <input name="name" placeholder="Pet Name" onChange={handleChange} required />
                    <input name="breed" placeholder="Breed" onChange={handleChange} required />
                    <input name="age" type="number" placeholder="Age" onChange={handleChange} required />

                    <div className="row">
                        <select name="type" onChange={handleChange}>
                            <option value="Dog">Dog</option>
                            <option value="Cat">Cat</option>
                            <option value="Bird">Bird</option>
                            <option value="Other">Other</option>
                        </select>
                        <select name="gender" onChange={handleChange}>
                            <option value="Male">Male</option>
                            <option value="Female">Female</option>
                        </select>
                    </div>

                    {/* IMAGE UPLOAD AREA */}
                    <div className="image-upload-section">
                        <label className="upload-btn">
                            <FaCloudUploadAlt size={24} />
                            <span>Upload Photos</span>
                            <input
                                type="file"
                                multiple
                                accept="image/*"
                                onChange={handleImageChange}
                                style={{ display: 'none' }}
                            />
                        </label>

                        {/* Preview Grid */}
                        <div className="preview-grid">
                            {images.map((img, index) => (
                                <div key={index} className="preview-card">
                                    <img src={img} alt="preview" />
                                    <button type="button" onClick={() => removeImage(index)}>
                                        <FaTimes />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>

                    <textarea name="description" placeholder="Description" onChange={handleChange} required />

                    <button type="submit" className="submit-btn" disabled={loading}>
                        {loading ? "Saving..." : "List Pet"}
                    </button>
                </form>
            </div>
        </div>
    );
};

export default AddPetPage;
